  const sentiments=['positive','neutral','negative','mixed','unknown'];const sentimentCounts=Object.fromEntries(sentiments.map(k=>[k,0]));let notAnalyzed=0;for(const t of tickets){if(sentiments.includes(t.sentiment))sentimentCounts[t.sentiment]++;else notAnalyzed++}
