    slot.innerHTML=card('AutoMod',`<p class="f-muted">${tr('Setiap aturan punya satu tindakan; warning, timeout, dan ban dapat sekaligus menghapus pesan pemicu jika opsi dinyalakan. Pesan dihapus setelah tindakan berhasil dan membutuhkan izin Manage Messages; kegagalan dilaporkan ke channel log. Catat saja tidak menghukum. Ban mengeluarkan anggota dan harus dikonfirmasi saat disimpan. Sejumlah aturan dapat salah mendeteksi: uji dengan catat saja dahulu.','Each rule has one action; warning, timeout and ban can also delete the triggering message if enabled. Deletion follows a successful action and requires Manage Messages; failures are reported to the log channel. Log only does not punish. Ban removes members and requires confirmation when saving. Rules can misdetect: test with log only first.')}</p><p class="f-muted">${tr('Isi pesan tidak disalin ke log. Deteksi direset saat restart; maksimal 30 laporan atau tindakan per menit per server dan satu tindakan per anggota per menit. Jika beberapa aturan cocok, hanya tindakan paling berat dijalankan.','Message content is not copied to logs. Detection resets on restart; at most 30 reports or actions per minute per server and one action per member per minute. If multiple rules match, only the most severe action runs.')}</p><form id="automodForm" class="f-form">${toggle('enabled',tr('Aktifkan AutoMod','Enable AutoMod'),settings.enabled)}${toggle('spamEnabled',tr('Deteksi spam','Detect spam'),settings.spamEnabled)}${field(tr('Jumlah pesan (3–20)','Message count (3–20)'),`<input type="number" name="spamCount" min="3" max="20" value="${esc(settings.spamCount)}" required>`)}${field(tr('Dalam waktu (3–120 detik)','Within (3–120 seconds)'),`<input type="number" name="spamSeconds" min="3" max="120" value="${esc(settings.spamSeconds)}" required>`)}${action('spamAction',tr('Tindakan spam','Spam action'))}${toggle('spamDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban spam','Also delete the message after spam warning, timeout or ban'),settings.spamDeleteAfter)}${ruleChannels('spam')}${toggle('mentionsEnabled',tr('Deteksi mass mention','Detect mass mentions'),settings.mentionsEnabled)}${field(tr('Jumlah anggota unik dalam satu pesan (2–20)','Unique members in one message (2–20)'),`<input type="number" name="mentionCount" min="2" max="20" value="${esc(settings.mentionCount)}" required>`)}${action('mentionsAction',tr('Tindakan mass mention','Mass mention action'))}${toggle('mentionsDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban mass mention','Also delete the message after mass mention warning, timeout or ban'),settings.mentionsDeleteAfter)}${ruleChannels('mentions')}<p class="f-muted">${tr('Hanya mention pengguna unik; role, everyone, dan bot tidak dihitung.','Only unique user mentions count; roles, everyone and bots are excluded.')}</p>${toggle('wordsEnabled',tr('Filter kata','Word filter'),settings.wordsEnabled)}${field(tr('Kata utuh · satu per baris','Whole words · one per line'),`<textarea name="wholeWords" rows="4" maxlength="2049" placeholder="${tr('Satu kata atau frasa per baris','One word or phrase per line')}">${esc(settings.wholeWords.join('\n'))}</textarea>`)}${field(tr('Bagian kata · satu per baris','Partial words · one per line'),`<textarea name="partialWords" rows="4" maxlength="2049" placeholder="${tr('Satu kata atau frasa per baris','One word or phrase per line')}">${esc(settings.partialWords.join('\n'))}</textarea>`)}${field(tr('Regex RE2 · satu per baris','RE2 regex · one per line'),`<textarea name="regexWords" rows="3" maxlength="1619" placeholder="${tr('satu pola per baris','one pattern per line')}">${esc(settings.regexWords.join('\n'))}</textarea>`)}<p class="f-muted">${tr('Maksimal 20 pola, 80 karakter per pola. Tidak mendukung lookaround atau backreference; pola yang cocok dengan teks kosong ditolak.','Up to 20 patterns, 80 characters each. Lookaround and backreferences are unsupported; patterns matching empty text are rejected.')}</p>${field(tr('Wildcard · satu per baris','Wildcard · one per line'),`<textarea name="wildcardWords" rows="3" maxlength="2049" placeholder="${tr('contoh*kata','example*word')}">${esc(settings.wildcardWords.join('\n'))}</textarea>`)}<p class="f-muted">${tr('Tanda * cocok dengan teks apa pun di antara bagian kata; bukan regex. Maksimal 5 tanda * per pola.','An * matches any text between word parts; it is not regex. Maximum 5 asterisks per pattern.')}</p><p class="f-muted">${tr('Maksimal 50 entri per daftar, masing-masing 2–40 karakter. Bagian kata dapat memicu kata lain secara tidak sengaja.','Up to 50 entries per list, each 2–40 characters. Partial words can accidentally match other words.')}</p>${action('wordsAction',tr('Tindakan filter kata','Word filter action'))}${toggle('wordsDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban filter kata','Also delete the message after word filter warning, timeout or ban'),settings.wordsDeleteAfter)}${ruleChannels('words')}${toggle('linksEnabled',tr('Filter link','Link filter'),settings.linksEnabled)}${toggle('blockInvites',tr('Blokir undangan Discord meskipun domain diizinkan','Block Discord invites even if the domain is allowed'),settings.blockInvites)}${field(tr('Domain yang diizinkan · satu per baris','Allowed domains · one per line'),`<textarea name="allowedDomains" rows="3" placeholder="${tr('contoh.com','example.com')}">${esc(settings.allowedDomains.join('\n'))}</textarea>`)}<p class="f-muted">${tr('Link web biasa diblokir kecuali domain atau subdomain dalam daftar. Deteksi tidak menjamin semua link tersamarkan terjangkau.','Ordinary web links are blocked unless their domain or subdomain is listed. Detection does not guarantee all disguised links are caught.')}</p>${action('linksAction',tr('Tindakan filter link','Link filter action'))}${toggle('linksDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban filter link','Also delete the message after link filter warning, timeout or ban'),settings.linksDeleteAfter)}${ruleChannels('links')}${toggle('repeatEnabled',tr('Deteksi pesan berulang','Detect repeated messages'),settings.repeatEnabled)}${field(tr('Jumlah pesan identik (2–20)','Identical message count (2–20)'),`<input type="number" name="repeatCount" min="2" max="20" value="${esc(settings.repeatCount)}" required>`)}${field(tr('Dalam waktu (3–120 detik)','Within (3–120 seconds)'),`<input type="number" name="repeatSeconds" min="3" max="120" value="${esc(settings.repeatSeconds)}" required>`)}${action('repeatAction',tr('Tindakan pesan berulang','Repeated message action'))}${toggle('repeatDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban pesan berulang','Also delete the message after repeated message warning, timeout or ban'),settings.repeatDeleteAfter)}${ruleChannels('repeat')}${toggle('capsEnabled',tr('Deteksi huruf kapital berlebihan','Detect excessive uppercase'),settings.capsEnabled)}${field(tr('Jumlah minimal huruf (5–500)','Minimum letter count (5–500)'),`<input type="number" name="capsMinimum" min="5" max="500" value="${esc(settings.capsMinimum)}" required>`)}${field(tr('Persentase huruf kapital (50–100)','Uppercase percentage (50–100)'),`<input type="number" name="capsPercent" min="50" max="100" value="${esc(settings.capsPercent)}" required>`)}${action('capsAction',tr('Tindakan huruf kapital','Uppercase action'))}${toggle('capsDeleteAfter',tr('Hapus pesan juga setelah warning, timeout, atau ban huruf kapital','Also delete the message after uppercase warning, timeout or ban'),settings.capsDeleteAfter)}${ruleChannels('caps')}${profiles()}${toggle('aiReviewEnabled',tr('Tinjauan AI untuk moderator','AI review for moderators'),settings.aiReviewEnabled)}${toggle('aiVisionEnabled',tr('Tinjauan gambar AI untuk moderator','AI image review for moderators'),settings.aiVisionEnabled)}<p class="f-muted">${tr('Opsional dan default mati; hanya saat tinjauan AI aktif. Satu gambar PNG/JPEG hingga 1 MB dari akun baru kurang dari 7 hari atau anggota yang bergabung kurang dari 24 jam di channel terpilih dapat dikirim ke provider AI dan cadangannya. Beri tahu anggota. Pemindaian dibatasi, dapat terlewat dan tidak menghukum otomatis.','Optional and off by default; requires AI review. One PNG/JPEG up to 1 MB from an account under 7 days old or member who joined under 24 hours ago in selected channels may be sent to AI providers and fallbacks. Inform members. Scans are limited, may be skipped, and never punish automatically.')}</p><fieldset class="f-field" aria-labelledby="automodaiReviewTitle" aria-describedby="automodaiReviewHelp"><span><b id="automodaiReviewTitle">${tr('Channel yang dikirim ke AI','Channels sent to AI')}</b><small id="automodaiReviewHelp">${tr('Pilih minimal satu channel; thread di dalamnya ikut dipantau. Hingga 1.000 karakter pesan yang terpilih dikirim ke provider AI eksternal (termasuk provider cadangan), bahkan jika tidak melanggar. Beritahu anggota sebelum mengaktifkan.','Select at least one channel; its threads are also monitored. Up to 1,000 characters of selected messages are sent to external AI providers (including fallbacks), even if they do not violate rules. Inform members before enabling.')}</small></span>${choices(data.channels,settings.aiReviewChannels,'aiReviewChannels')}</fieldset><p class="f-muted">${tr('AI hanya memberi tanda untuk ditinjau moderator, tidak menghukum atau menghapus pesan. Maksimal 3 pesan per menit dan satu permintaan bersamaan; pesan lain dilewati. Keluaran bisa keliru dan pemakaian AI berlaku.','AI only flags messages for moderator review; it does not punish or delete them. Maximum 3 messages per minute and one concurrent request; other messages are skipped. Output can be wrong and AI usage applies.')}</p>${toggle('escalationEnabled',tr('Timeout setelah warning mencapai batas','Timeout when warnings reach the threshold'),settings.escalationEnabled)}${field(tr('Batas warning aktif (2–20)','Active warning threshold (2–20)'),`<input type="number" name="escalationThreshold" min="2" max="20" value="${esc(settings.escalationThreshold)}" required>`)}${field(tr('Durasi timeout eskalasi (menit, 1–40320)','Escalation timeout duration (minutes, 1–40320)'),`<input type="number" name="escalationMinutes" min="1" max="40320" value="${esc(settings.escalationMinutes)}" required>`)}<p class="f-muted">${tr('Dipicu saat warning AutoMod, dashboard, atau /warn mencapai tepat batas. Semua warning aktif, termasuk yang lama dan manual, dihitung; warning yang dihapus tidak dihitung. Tidak memperpanjang timeout aktif. Menghapus warning dapat memungkinkan pemicu kembali.','Triggers when AutoMod, dashboard or /warn warnings reach exactly the threshold. All active warnings count, including old and manual ones; deleted warnings do not. It does not extend an active timeout. Deleting warnings can allow it to trigger again.')}</p>${toggle('raidEnabled',tr('Peringatan lonjakan anggota masuk','Member join surge alert'),settings.raidEnabled)}${field(tr('Jumlah anggota masuk (3–100)','Join count (3–100)'),`<input type="number" name="raidCount" min="3" max="100" value="${esc(settings.raidCount)}" required>`)}${field(tr('Dalam waktu (5–300 detik)','Within (5–300 seconds)'),`<input type="number" name="raidSeconds" min="5" max="300" value="${esc(settings.raidSeconds)}" required>`)}${toggle('raidLockEnabled',tr('Kunci channel terpilih saat lonjakan','Lock selected channels during a surge'),settings.raidLockEnabled)}<fieldset class="f-field" aria-labelledby="automodraidLockTitle" aria-describedby="automodraidLockHelp"><span><b id="automodraidLockTitle">${tr('Channel untuk lockdown','Channels for lockdown')}</b><small id="automodraidLockHelp">${tr('Maksimal 10. Bot menolak izin kirim @everyone dan mencatat izin sebelumnya di log. Tidak mengunci role yang punya izin khusus.','Maximum 10. The bot denies @everyone send permissions and records prior permissions in the log. Roles with specific permissions are not locked.')}</small></span>${choices(data.channels,settings.raidLockChannels,'raidLockChannels')}</fieldset><p class="f-muted">${tr('Lockdown tidak dipulihkan otomatis: moderator harus memeriksa log dan mengembalikan izin secara manual. Role dengan izin khusus atau Administrator mungkin masih dapat mengirim. Hitungan direset saat restart.','Lockdown is not restored automatically: moderators must check logs and restore permissions manually. Roles with specific permissions or Administrator may still send. Counts reset on restart.')}</p>${field(tr('Durasi ban AutoMod (menit, 0–40320; 0 permanen)','AutoMod ban duration (minutes, 0–40320; 0 permanent)'),`<input type="number" name="temporaryBanMinutes" min="0" max="40320" value="${esc(settings.temporaryBanMinutes)}" required>`)}<p class="f-muted">${tr('Ban sementara disimpan dan diperiksa setelah restart. Bot memeriksa alasan ban sebelum unban; jangan gunakan bersamaan dengan perubahan ban manual tanpa memeriksa jadwal. Discord tidak menyediakan pembatalan bersyarat yang sepenuhnya atomik.','Temporary bans are saved and checked after restart. The bot checks the ban reason before unbanning; do not combine with manual ban changes without checking the schedule. Discord does not offer fully atomic conditional unbans.')}</p>${field(tr('Durasi timeout (menit, 1–40320)','Timeout duration (minutes, 1–40320)'),`<input type="number" name="timeoutMinutes" min="1" max="40320" value="${esc(settings.timeoutMinutes)}" required>`)}<p class="f-muted">${tr('Owner server, anggota berizin admin, kelola server, timeout, kick atau ban, dan role yang dikecualikan tidak ditindak. Bot memerlukan izin dan hierarki yang sesuai. Timeout yang sedang aktif tidak diperpendek.','The server owner, members with admin, manage server, timeout, kick or ban permissions, and excluded roles are not acted on. The bot needs appropriate permissions and hierarchy. Active timeouts are not shortened.')}</p>${field(tr('Channel log','Log channel'),`<select name="logChannelId"><option value="">${tr('Pilih channel log','Choose log channel')}</option>${settings.logChannelId&&!data.channels.some(c=>c.id===settings.logChannelId)?`<option value="${esc(settings.logChannelId)}" selected>${tr('Channel tersimpan tidak tersedia — pilih ulang','Saved channel unavailable — select again')} · ID ${esc(settings.logChannelId)}</option>`:''}${data.channels.map(c=>`<option value="${esc(c.id)}" ${settings.logChannelId===c.id?'selected':''}># ${esc(c.name)}${!c.name||data.channels.filter(other=>other.name===c.name).length>1?` · ID ${esc(c.id)}`:''}</option>`).join('')}</select>`)}<fieldset class="f-field" aria-labelledby="automodignoredChannelsTitle" aria-describedby="automodignoredChannelsHelp"><span><b id="automodignoredChannelsTitle">${tr('Channel dikecualikan','Excluded channels')}</b><small id="automodignoredChannelsHelp">${tr('Maksimal 50. Thread pada channel itu juga dikecualikan.','Maximum 50. Threads in those channels are also excluded.')}</small></span>${choices(data.channels,settings.ignoredChannels,'ignoredChannels')}</fieldset><fieldset class="f-field" aria-labelledby="automodignoredRolesTitle" aria-describedby="automodignoredRolesHelp"><span><b id="automodignoredRolesTitle">${tr('Role dikecualikan','Excluded roles')}</b><small id="automodignoredRolesHelp">${tr('Maksimal 50.','Maximum 50.')}</small></span>${choices(data.roles,settings.ignoredRoles,'ignoredRoles')}</fieldset><div class="f-form-actions"><span>${tr('PERIKSA TINDAKAN SEBELUM MENYIMPAN','REVIEW ACTIONS BEFORE SAVING')}</span><button class="f-primary" type="submit">${tr('SIMPAN','SAVE')}</button></div></form>`);
    const form=slot.querySelector('#automodForm');
